                "returns": {
                  "allowed": false,
                  "policyRef": "ion://policy/return.standard.7d-sellerpays"
                },
                "cancellation": {
                  "policyRef": "ion://policy/cancel.prepacked.free"
                },
                "warranty": {
                  "policyRef": "ion://policy/warranty.standard.none"
                },
                "dispute": {
                  "policyRef": "ion://policy/dispute.consumer.bpsk"
                },
                "grievanceSla": {
                  "policyRef": "ion://policy/grievance-sla.consumer.standard"
                },
                "paymentTerms": {
                  "policyRef": "ion://policy/payment-terms.upfront.full"
                },
                "settlement": {
                  "settlementBasis": "AFTER_DELIVERY",
                  "settlementWindow": "P1D"
                }
              },
              "timeToShip": "PT30M",
              "paymentConstraints": {
                "codAvailable": true
              },
              "contactDetailsConsumerCare": {
                "name": "Customer Service",
                "email": "cs@dominos-sudirman.id",
                "phone": "+6221-5555-1234"
              },
              "customization": {
                "groups": [
                  {
                    "code": "CG-CRUST",
                    "name": "Pizza Crust",
                    "selection": "SINGLE_REQUIRED",
                    "options": [
                      {
                        "code": "OPT-THIN",
                        "name": "Thin Crust",
                        "priceDelta": {
                          "type": "FIXED",
                          "value": 0
                        },
                        "available": true
                      },
                      {
                        "code": "OPT-PAN",
                        "name": "Pan Crust",
                        "priceDelta": {
                          "type": "FIXED",
                          "value": 5000
                        },
                        "available": true
                      }
                    ]
                  },
                  {
                    "code": "CG-SAUCE",
                    "name": "Sauce",
                    "selection": "SINGLE_REQUIRED",
                    "options": [
                      {
                        "code": "OPT-TOMATO",
                        "name": "Tomato Sauce",
                        "priceDelta": {
                          "type": "FIXED",
                          "value": 0
                        },
                        "available": true
                      },
                      {
                        "code": "OPT-BBQ",
                        "name": "BBQ Sauce",
                        "priceDelta": {
                          "type": "FIXED",
                          "value": 3000
                        },
                        "available": true
                      }
                    ]
                  }
                ]
              },
              "displayLanguage": [
                "id"
              ]
            },
            "considerations": [
              {
                "id": "CONSID-OFFER-PIZZA-001",
                "considerationAttributes": {
                  "@context": "https://schema.ion.id/release1/schema/extension/trade/TradeConsideration/v1/context.jsonld",
                  "@type": "ion:IONTradeConsideration",
                  "currency": "IDR",
                  "totalAmount": 89000,
                  "breakup": [
                    {
                      "title": "Harga",
                      "amount": 89000,
                      "type": "BASE_PRICE"
                    }
                  ],
                  "buyerFinderFee": {
                    "feeType": "PERCENT",
                    "feeValue": 3,
                    "appliesTo": "ITEM_TOTAL"
                  }
                }
              }
            ]
          }
        ]
      }
    ]
  }
}

